Now let me write the code. New enableAutoMergeOnPr:

```ts
/**
 * Enable auto-merge (squash) on a Forgejo PR, schedule-first:
 *
 * 1. Schedule (gate): POST merge with `merge_when_checks_succeed` (and
 *    optionally `head_commit_id`). Errors here are surfaced as `{ok:false}`
 *    and NO direct merge is attempted — the discovery gate ("allow auto-merge")
 *    remains load-bearing: without schedule support we do no merge at all.
 * 2. Opportunistic direct merge: after a successful schedule, attempt a
 *    direct squash-merge (body without `merge_when_checks_succeed`, but
 *    still with `head_commit_id` when given). Bounded retry (max 3,
 *    `directMergeBackoffMs` backoff, default 500ms) so transient mergeability
 *    issues don't block.
 *
 * We deliberately do NOT branch on the direct merge error: when all attempts
 * fail we keep the schedule standing (`mode: 'scheduled'`); on success
 * `mode: 'merged'`.
 *
 * PBI-47 (P0): ... head_commit_id guard.
 */
export async function enableAutoMergeOnPr(opts: {
  prUrl: string
  expectedHeadSha?: string
  cwd?: string
  /** Test-only: backoff between direct-merge retries (default 500ms). */
  directMergeBackoffMs?: number
}): Promise<EnableAutoMergeResult> {
  let prRef
  try {
    prRef = parseForgejoPrUrl(opts.prUrl)
  } catch (err) {
    return forgejoErrorToAutoMergeResult(err)
  }

  try {
    const discovery = await discoverForgejo(prRef.host)
    if (!discovery.supportsAutoMerge) {
      return {...}
    }
  } catch (err) {
    return forgejoErrorToAutoMergeResult(err)
  }

  const mergePath = `${repoPath(prRef.owner, prRef.repo)}/pulls/${prRef.index}/merge`

  // 1. Schedule (gate)
  const scheduleBody: Record<string, unknown> = {
    Do: 'squash',
    merge_when_checks_succeed: true,
  }
  if (opts.expectedHeadSha) scheduleBody.head_commit_id = opts.expectedHeadSha

  try {
    await callForgejo(mergePath, { method: 'POST', write: true, host: prRef.host, json: scheduleBody })
  } catch (err) {
    return forgejoErrorToAutoMergeResult(err)
  }

  // 2. Opportunistic direct merge, bounded retry (max 3)
  const directBody: Record<string, unknown> = { Do: 'squash' }
  if (opts.expectedHeadSha) directBody.head_commit_id = opts.expectedHeadSha
  const backoffMs = opts.directMergeBackoffMs ?? 500

  for (let attempt = 1; attempt <= DIRECT_MERGE_MAX_ATTEMPTS; attempt++) {
    try {
      await callForgejo(mergePath, { method: 'POST', write: true, host: prRef.host, json: directBody })
      return { ok: true, mode: 'merged' }
    } catch (err) {
      if (attempt < DIRECT_MERGE_MAX_ATTEMPTS && backoffMs > 0) {
        await new Promise((resolve) => setTimeout(resolve, backoffMs * attempt))
      }
    }
  }

  console.warn(
    `[enableAutoMergeOnPr] directe squash-merge na ${DIRECT_MERGE_MAX_ATTEMPTS} pogingen niet geslaagd voor ${opts.prUrl}; schedule blijft staan (mode: scheduled)`,
  )
  return { ok: true, mode: 'scheduled' }
}
```

