 * Zet auto-merge (squash) aan op een Forgejo PR met optionele head-SHA guard.
 *
 * PBI-47 (P0): wanneer `expectedHeadSha` meegegeven wordt sturen we
 * `head_commit_id` mee in de merge-body; Forgejo activeert dan alleen
 * auto-merge wanneer de remote head nog matcht. Dit voorkomt dat een
 * latere worker-push een ongewenste commit-set mergt.
 *
 * Wanneer de Forgejo-instance `merge_when_checks_succeed` niet ondersteunt
 * (discovery faalt op dat veld) retourneren we `AUTO_MERGE_NOT_ALLOWED`
 * zónder een merge-call te doen — direct mergen is bewust géén fallback.
 */
export async function enableAutoMergeOnPr(opts: {
  prUrl: string
  expectedHeadSha?: string
  cwd?: string
}): Promise<EnableAutoMergeResult> {
  let prRef
  try {
    prRef = parseForgejoPrUrl(opts.prUrl)
  } catch (err) {
    return forgejoErrorToAutoMergeResult(err)
  }

  try {
    const discovery = await discoverForgejo(prRef.host)
    if (!discovery.supportsAutoMerge) {
      return {
        ok: false,
        reason: 'AUTO_MERGE_NOT_ALLOWED',
        stderr: `Forgejo ${discovery.version} mist merge_when_checks_succeed in OpenAPI`,
      }
    }
  } catch (err) {
    return forgejoErrorToAutoMergeResult(err)
  }

  const body: Record<string, unknown> = {
    Do: 'squash',
    merge_when_checks_succeed: true,
  }
  if (opts.expectedHeadSha) body.head_commit_id = opts.expectedHeadSha

  try {
    await callForgejo(
      `${repoPath(prRef.owner, prRef.repo)}/pulls/${prRef.index}/merge`,
      {
        method: 'POST',
        write: true,
        host: prRef.host,
        json: body,
      },
    )
    return { ok: true }
  } catch (err) {
    return forgejoErrorToAutoMergeResult(err)
  }
}", "new_string": "/**
 * Zet auto-merge (squash) aan op een Forgejo PR met optionele head-SHA guard.
 *
 * PBI-47 (P0): wanneer `expectedHeadSha` meegegeven wordt sturen we
 * `head_commit_id` mee in de merge-body; Forgejo activeert dan alleen
 * auto-merge wanneer de remote head nog matcht. Dit voorkomt dat een
 * latere worker-push een ongewenste commit-set mergt.
 *
 * M22 (PBI-130): schedule-first + opportunistiche directe merge.
 *  1. Discovery-gate (ongewijzigd): `merge_when_checks_succeed` mist →
 *     `AUTO_MERGE_NOT_ALLOWED` zónder merge-call.
 *  2. Schedule-POST (`merge_when_checks_succeed: true`). Fout → surface
 *     `{ok:false}`; de directe merge is géén fallback op een schedule-fout.
 *  3. Opportunistische directe squash-merge in een max-3 bounded-retry-lus
 *     (dekt transiënte mergeability). Fouten op de directe call laten de
 *     schedule gewoon staan → `{ok:true, mode:'scheduled'}`; slaagt 'ie →
 *     `{ok:true, mode:'merged'}`. `head_commit_id` zit in béíde bodies.
 */
export async function enableAutoMergeOnPr(opts: {
  prUrl: string
  expectedHeadSha?: string
  cwd?: string
  /** Milliseconden tussen directe-merge pogingen (default 500; 0 in tests). */
  directMergeBackoffMs?: number
}): Promise<EnableAutoMergeResult> {
  let prRef
  try {
    prRef = parseForgejoPrUrl(opts.prUrl)
  } catch (err) {
    return forgejoErrorToAutoMergeResult(err)
  }

  try {
    const discovery = await discoverForgejo(prRef.host)
    if (!discovery.supportsAutoMerge) {
      return {
        ok: false,
        reason: 'AUTO_MERGE_NOT_ALLOWED',
        stderr: `Forgejo ${discovery.version} mist merge_when_checks_succeed in OpenAPI`,
      }
    }
  } catch (err) {
    return forgejoErrorToAutoMergeResult(err)
  }

  const mergePath = `${repoPath(prRef.owner, prRef.repo)}/pulls/${prRef.index}/merge`

  // 1. Schedule-first: auto-merge zodra checks slagen (respecteert de gate).
  const scheduleBody: Record<string, unknown> = {
    Do: 'squash',
    merge_when_checks_succeed: true,
  }
  if (opts.expectedHeadSha) scheduleBody.head_commit_id = opts.expectedHeadSha

  try {
    await callForgejo(mergePath, {
      method: 'POST',
      write: true,
      host: prRef.host,
      json: scheduleBody,
    })
  } catch (err) {
    // Schedule-fout → surface; géén directe-merge fallback.
    return forgejoErrorToAutoMergeResult(err)
  }

  // 2. Opportunistische directe merge: slaat als de PR nu al mergeable is.
  //    Max 3 pogingen met backoff voor transiënte mergeability; een mislukte
  //    lus laat de schedule staan (mode 'scheduled') — géén ok:false.
  const directBody: Record<string, unknown> = { Do: 'squash' }
  if (opts.expectedHeadSha) directBody.head_commit_id = opts.expectedHeadSha

  const maxAttempts = 3
  const backoffMs = opts.directMergeBackoffMs ?? 500
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      await callForgejo(mergePath, {
        method: 'POST',
        write: true,
        host: prRef.host,
        json: directBody,
      })
      return { ok: true, mode: 'merged' }
    } catch (err) {
      if (attempt === maxAttempts) break
      if (backoffMs > 0) {
        await new Promise((resolve) => setTimeout(resolve, backoffMs))
      }
    }
  }

  console.warn(
    `[enableAutoMergeOnPr] directe merge faalde na ${maxAttempts} pogingen voor ${opts.prUrl}; scheduled auto-merge blijft staan`,
  )
  return { ok: true, mode: 'scheduled' }
}"}

